svg.metadata:
flowchart TB
  A["cron / trigger: identify occurrenceId"]
  B["Atomic database claim; assign execution token and deadline"]
  C["Execute and renew; conditionally commit actual outcome"]
  V["Commit valid outcome in time; finish this occurrence"]
  D["Old attempt expires with unconfirmed outcome"]
  E{"idempotent=true with attempts remaining?"}
  F["Start another attempt with the same occurrenceId"]
  U["unknown: pause future occurrences and reconcile"]
  A --> B
  B --> C
  C -->|"completes normally"| V
  C -->|"expired and unconfirmed"| D
  D --> E
  E -->|"yes"| F
  F --> B
  E -->|"no"| U
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class V good;
  class D,U pending;
